import AbstractApiService from 'src/services/abstractApiService';
import { api, getAuthorizationToken } from 'pages/APIs';
import axios, { AxiosResponse } from 'axios';
import { cloudFile } from 'src/doc2light/components/store-types';
import { SpaceFile } from '../components/space-types';

import { request } from 'http';
import string from 'src/utils/string';

export interface StoreReponse {
  success: boolean;
  store: string;
  folders: RequestSpaceFolder[];
  files: SpaceFile[];
}

export type RequestSpaceFolder = {
  label: string;
  path: string;
  id: string;
  children: string[] | null;
};

export interface FolderReponse {
  success: boolean;
  store: string;
  folders: RequestFolder[];
}

export type RequestFolder = {
  id: string;
  label: string;
  children: any[] | null;
  children_ids: string[] | null;
};

export default class AlfredSpaceServiceV2 extends AbstractApiService {
  public constructor({}) {
    super({});
  }

  init_auth(formData: FormData) {
    return super.post(api.init_auth, formData);
  }

  getStoreFiles(file_path: string, id: string): Promise<StoreReponse> {
    const queryParams = '?store_id=' + id;
    return super.get(api.get_store_content + queryParams);
  }

  getStoreFolders(file_path: string, id: string): Promise<FolderReponse> {
    const queryParams = '?store_id=' + id;
    return super.get(api.get_store_content + queryParams);
  }

  getFolders(store_id: string): Promise<FolderReponse> {
    const queryParams = '?store_id=' + store_id;
    return super.get(api.get_folders + queryParams);
  }

  uploadFiletoGDrive(
    file: any,
    path: cloudFile,
    store_id: string,
  ): Promise<Record<string, boolean>> {
    let queryParams = '';
    queryParams += '?path=' + path.id + '&store_id=' + store_id;

    const formData = new FormData();
    formData.append('file', file);

    return super.post(api.upload_files + queryParams, formData);
  }

  uploadFiletoSpace(
    doc_ids: string[],
    file: SpaceFile,
    overwrite = false,
    store_type: string,
    store_id: string,
  ): Promise<Record<string, boolean>> {
    let queryParams = '';
    if (store_type == 'googledrive' || store_type == 'onedrive') {
      queryParams +=
        '?path=' +
        file.id +
        '&overwrite=' +
        overwrite +
        '&store_id=' +
        store_id;
    } else if (store_type == 'dropbox') {
      queryParams +=
        '?path=' +
        file.path +
        '&overwrite=' +
        overwrite +
        '&store_id=' +
        store_id;
    } else if (store_type == 'lexoffice') {
      queryParams += '?store_id=' + store_id;
    }

    const formData = new FormData();
    for (const [key, value] of Object.entries(doc_ids)) {
      formData.append(key, value);
    }
    return super.post(api.upload_files + queryParams, formData);
  }

  importSpaceFileToAlfred(
    file: SpaceFile,
    id: string,
    store_type: string,
  ): Promise<string[]> {
    const request_array: string[] = [];
    if (store_type == 'GoogleDrive' || store_type == 'Onedrive') {
      request_array.push(file.id);
    } else {
      request_array.push(file.path);
    }
    const queryParams = '?store_id=' + id;
    const formData = new FormData();
    for (const [key, value] of Object.entries(request_array)) {
      formData.append(key, value);
    }

    return super.post(api.import_files + queryParams, formData);
  }

  async downloadFileFromSpace(
    file: SpaceFile,
    id: string,
    store_type: string,
  ): Promise<string> {
    const token = await getAuthorizationToken();
    const queryParams = '?store_id=' + id;
    const request_array: string[] = [];
    if (store_type == 'GoogleDrive' || store_type == 'Onedrive') {
      request_array.push(file.id);
    } else {
      request_array.push(file.path);
    }

    const response = await axios.post(
      api.download_files + queryParams,
      request_array,
      {
        responseType: 'blob',
        headers: {
          Authorization: token,
        },
      },
    );
    return URL.createObjectURL(
      new Blob([
        response.data,
        file.label + 'pdf',
        response.headers['content-type'],
      ]),
    );
  }
}
