import axios from 'axios';
import { AxiosResponse } from 'axios';
import type { dynamicObj } from 'src/pages/assets';
import { api, getAuthorizationToken } from 'pages/APIs';
import AbstractApiService from 'src/services/abstractApiService';

export default class DocumentDetailApiService extends AbstractApiService {
  public constructor({}) {
    super({});
  }

  getById(id: string): Promise<AxiosResponse<any>> {
    return super.get(api.get_doc + id);
  }

  get_all_docs(): Promise<AxiosResponse<any>> {
    return super.get(api.all_documents);
  }

  dashboard(queryParams: string): Promise<AxiosResponse<any>> {
    return super.get(api.dashboard + queryParams);
  }

  create_doc(formData: FormData): Promise<AxiosResponse<any>> {
    const config = {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    };
    return super.post(api.create_doc, formData, config);
  }
  get_directscan_documents() {
    return super.get(api.get_directscan_documents);
  }
  split_ocr_and_upload_to_store(
    name: string,
    path: string,
    store_id: string,
    file: any,
    auto_doc_name: boolean,
    separators: string,
    sorted_indexes: string,
    deleted_indexes: string,
  ) {
    const queryParams =
      '?name=' +
      name +
      '&path=' +
      path +
      '&store_id=' +
      store_id +
      '&auto_name=' +
      auto_doc_name;
    const formData = new FormData();
    formData.append('file', file);
    formData.append('separators', separators);
    formData.append('sorted_indexes', sorted_indexes);
    formData.append('deleted_indexes', deleted_indexes);
    return super.post(api.split_ocr_upload + queryParams, formData);
  }

  ocr_upload_to_store(
    name: string,
    path: string,
    store_id: string,
    file: any,
    auto_doc_name: boolean,
  ) {
    const queryParams =
      '?name=' +
      name +
      '&path=' +
      path +
      '&store_id=' +
      store_id +
      '&auto_name=' +
      auto_doc_name;
    const formData = new FormData();
    formData.append('file', file);
    return super.post(api.ocr_upload_to_store + queryParams, formData);
  }

  async split_create_doc(
    file: any,
    seperators: string,
    stored_indexes: string,
    deleted_indexes: string,
  ): Promise<AxiosResponse<any>> {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('separators', seperators);
    formData.append('sorted_indexes', stored_indexes);
    formData.append('deleted_indexes', deleted_indexes);
    return super.post(api.split_create_doc, formData);
  }

  async split_old_doc(
    file: any,
    seperators: string,
    stored_indexes: string,
    deleted_indexes: string,
  ): Promise<AxiosResponse<any>> {
    const formData = new FormData();
    formData.append('doc_id', file);
    formData.append('separators', seperators);
    formData.append('sorted_indexes', stored_indexes);
    formData.append('deleted_indexes', deleted_indexes);
    return super.post(api.split_old_doc, formData);
  }

  delete_doc_by_id(id: string): Promise<AxiosResponse<any>> {
    const formData = new FormData();
    formData.append('doc_id', id);
    return super.delete(api.delete_doc, formData);
  }

  async download_doc(id: string): Promise<any> {
    const token = await getAuthorizationToken();
    const response = await axios.get(
      api.download_doc + '/' + id,

      {
        responseType: 'blob',
        headers: {
          Authorization: token,
        },
      },
    );
    return URL.createObjectURL(
      new Blob([response.data, id + '.pdf', response.headers['content-type']]),
    );

    // return super.get(api.download_doc + '/' + id);
  }

  async getThumbnail(id: string): Promise<AxiosResponse<any>> {
    const token = await getAuthorizationToken();
    const response = await axios.get(
      api.get_doc_thumbnail + id,

      {
        responseType: 'blob',
        headers: {
          Authorization: token,
        },
      },
    );

     
    return response.data;

    //return super.get(api.get_doc_thumbnail + id);
  }

  get_doc_text(id: string): Promise<AxiosResponse<any>> {
    const formData = new FormData();
    formData.append('doc_id', id);
    return super.get(api.get_doc_text + '/' + id, formData);
  }

  update_doc(
    id: string,
    name: string,
    asi: string,
    correspondent: string,
    doc_type: string,
    tags: any,
  ): Promise<AxiosResponse<any>> {
    let queryParams: string = id;

    if (name !== '') {
      queryParams += '?name=' + name;
    }
    if (asi !== '') {
      queryParams += '&asi_num=' + asi;
    }
    if (correspondent !== undefined) {
      queryParams += '&correspondent=' + correspondent;
    }
    if (doc_type !== undefined) {
      queryParams += '&doc_type=' + doc_type;
    }
    if (tags !== '') {
      queryParams += '&tags=' + tags;
    }
    return super.put(api.update_doc + queryParams, new FormData());
  }

  remove_tag_from_doc(
    doc_id: string,
    tag_id: string,
  ): Promise<AxiosResponse<any>> {
    const formData = new FormData();
    formData.append('doc_id', doc_id);
    formData.append('tag_id', tag_id);
    return super.put(api.remove_tag_from_doc, formData);
  }

  performDocSplit(data: dynamicObj, id: string): Promise<AxiosResponse<any>> {
    const formData = new FormData();
    formData.append('doc_id', id);
    for (const [key, value] of Object.entries(data)) {
      formData.append(key, value);
    }

    return super.post(api.split_document, formData);
  }
}
