<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { date } from 'quasar';
import DocSplit from 'src/doc2light/components/popups/split_document.vue';
import axios from 'axios';
import { documentListApiService } from 'src/services';
import VuePdfEmbed from 'vue-pdf-embed';
import DownloadInstaller from 'src/doc2light/components/popups/install_scanner.vue';
export default defineComponent({
  data() {
    return {};
  },
  props: ['service'],
  components: {
    DocSplit,
    VuePdfEmbed,
    DownloadInstaller,
  },
  mixins: [helperMixin],
  mounted() {
    logInfo(this.service);
    var url = 'https://local.polydocs.io:';
    this.initView(url);
  },
  methods: {
    initView(url: string) {
      this.new_scan['automatic_get'] = false;
      this.new_scan['remove_empty_sites'] = false;
      this.new_scan['2_sided'] = false;
      this.new_scan['pixel_type'] = this.pixeltypes[0];
      this.new_scan['resolution'] = this.resolutions[0];
      this.checkAlfred(url);
    },

    async checkAlfred(url: string) {
      try {
        await axios.get(url + '12500/');
        await this.getScanners(url + '12500/');
      } catch (error) {
        try {
          await axios.get(url + '12154/');
          await this.getScanners(url + '12154/');
        } catch (error) {
          try {
            await axios.get(url + '12346/');
            await this.getScanners(url + '12346/');
          } catch (error) {
            notify.error(this.$t('no_running_scanner'));
            this.showDownloadInstallerButton = true;
            this.showInstaller = true;
            this.showDragnDrop = false;
          }
        }
      }
    },
    async getScanners(url: any) {
      this.valid_url = url;
      const response: any = await axios.get(url + 'scanners');
      if (response.data.success == true) {
        this.scanners = [];
        response.data.scanners.forEach((scanner: any) => {
          this.scanners.push({
            value: scanner['Host'],
            label: scanner['Device'],
          });
        });
        this.new_scan['source'] = this.scanners[0];
      } else {
        logInfo(response);
        notify.error(this.$t('no_scanner_found'));
      }
    },
    async doScan() {
      if (!this.new_scan['source']) {
        notify.error(this.$t('no_scanner_found'));
        return;
      }
      let url =
        this.valid_url + 'scan?host=' + this.new_scan['source']['value'];
      if (this.new_scan['automatic_get'] == true) {
        url = url + '&source=adf';
      } else {
        url = url + '&source=platen';
      }
      if (this.new_scan['pixel_type']['value'] != '') {
        url = url + '&color=' + this.new_scan['pixel_type']['value'];
      }
      if (this.new_scan['2_sided'] != '') {
        url = url + '&duplex_input=' + this.new_scan['2_sided'];
      }
      this.showLoading();
      let response = await axios
        .get(url, { responseType: 'blob' })
        .then((response) => {
          const content = response.headers['content-type'];
          const blob = new Blob([response.data, 'test.pdf', content]);
          this.file = URL.createObjectURL(response.data);
          if (this.new_scan['automatic_get']) {
            this.showSplitButton = true;
          }
          this.showInstaller = false;
          this.showDragnDrop = false;
          this.showPDF = true;
          this.documentScanned = true;
          this.filedata = response.data;
        })
        .catch((error: any) => logError(error));
      this.hideLoading();
    },
    getRef() {
      let count: number = (this.$refs['pager'] as any).pageCount;
      return count;
    },
    formateDate(strDate: string, dateFormet: string) {
      return date.formatDate(strDate, dateFormet);
    },
    allowDrop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.add('highlighted-back');
      event.currentTarget.classList.add('bd-shadow');
    },
    drop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.remove('highlighted-back');
      event.currentTarget.classList.remove('bd-shadow');
      logInfo(event.dataTransfer.files);
      this.uploadFiles(event.dataTransfer.files);
    },
    dragLeave(event: any) {
      event.currentTarget.classList.remove('highlighted-back');
      event.currentTarget.classList.remove('bd-shadow');
    },
    downloadInstaller(url: any) {
      window.open(url, '_self');
    },
    async uploadFiles(files: any) {
      this.showLoading();
      logInfo(files);
      for (const file in files) {
        try {
          let formData = new FormData();
          var data = files[file];
          logInfo(data);
          formData.append('files', data);

          await documentListApiService.uploadFiles(formData);
        } catch (err) {
          logError(err);
        }
      }
      this.hideLoading();
      this.$router.push('/dashboard');
    },

    async uploadSingleFile(file: any) {
      this.showLoading();
      try {
        let formData = new FormData();
        if (this.new_scan['name']) {
          formData.append('files', file, this.new_scan['name'] + '.pdf');
        } else {
          formData.append('files', file, 'Scan.pdf');
        }
        logInfo(file);
        await documentListApiService.uploadFiles(formData);
      } catch (err) {
        logError(err);
      }
      this.hideLoading();
      this.$router.push('/dashboard');
    },
  },
  setup() {
    const pixeltypes = [
      // {value: 'black_white', label: ('Black&White')},
      { value: 'Grayscale8', label: 'Gray' },
      { value: 'RGB24', label: 'Color' },
    ];
    const resolutions = [
      { value: '300', label: '300' },
      { value: '600', label: '600' },
      { value: '1200', label: '1200' },
    ];

    return {
      showDragnDrop: ref(true),
      showInstaller: ref(false),
      showDownloadInstallerButton: ref(false),
      showDownloadInstaller: ref(false),
      pageCount: ref(1),
      file: ref(),
      filedata: ref(),
      filter: ref(''),
      view: ref('list'),
      multiUploaderDialog: ref(false),
      uploadedFiles: ref(null),
      image: ref(),
      new_scan: ref({} as any),
      scanners: ref([] as any),
      show_popup: ref(false),
      pixeltypes: ref(pixeltypes),
      resolutions: ref(resolutions),
      importing: ref(false),
      showSplitButton: ref(false),
      showMenu: ref(false),
      showIcons: ref(true),
      documentScanned: ref(false),
      ports: ref(['12500', '12154', '12346']),
      valid_url: ref(),
      scan_card_height: ref(),
      showPDF: ref(false),
    };
  },
});
</script>

