 
import { defineStore } from 'pinia';
import axios from 'axios';
import {
  documentdetailservice,
  storedetailservice,
  alfredSpaceService,
} from 'src/doc2light/services';

import { cloudStore, cloudFolder } from 'src/doc2light/components/store-types';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';

const root_folder: cloudFolder = {
  id: '',
  label: '/',
  children: [] as any,
  children_ids: [] as any,
  saved: 0,
};

export const useDirectscanStore = defineStore('scanner_store', {
  state: () => ({
    valid_url: 'https://local.polydocs.io:',
    scanners: [] as any,

    file: '',
    filedata: {} as any,
    pager: {} as any,
    page_count: 0 as number,
    current_carousel_name: 'store' as string,
    carousel_names: ['store', 'scan', 'documents'] as string[],
    folder_selection: true as boolean,
    new_scan: {} as any,

    showDownloadInstallerButton: false,
    showDragDrop: true,
    showSplitButton: false,
    no_store: true,
    loading: false,
    showPulsating: true,

    current_store: {} as cloudStore,
    stores: [] as any,
    shown_folders: {} as any,
    folders: {} as any,
    documents: [] as any,
    saved_folders: [] as any,
    root_folder: root_folder,
    current_folder: {} as cloudFolder,
    current_folder_url: '' as string,
    store_type: 'google_drive',
    oauthToken: null,
  }),

  getters: {
    getShowDownloadInstallerButton: (state) =>
      state.showDownloadInstallerButton,

    getScannersfromStore: (state) => state.scanners,

    getFiledata: (state) => state.filedata,
    getFile: (state) => state.file,

    getUrl: (state) => state.valid_url,
    getCurrentStore: (state) => state.current_store,
    getCurrentFolder: (state) => state.current_folder,
    getTableDocuments: (state) => state.documents,

    getPageCount: (state) => state.page_count,
    getBackDisable: (state) => state.page_count > 0,
    getNextDisable: (state) => state.page_count < 2,
    getCarouselName: (state) => state.current_carousel_name,
  },

  actions: {
    subtractPage() {
      this.page_count = this.getPageCount - 1;
      this.current_carousel_name = this.carousel_names[this.getPageCount];
    },

    addPage() {
      this.page_count = this.getPageCount + 1;
      this.current_carousel_name = this.carousel_names[this.getPageCount];
    },
    async getStore() {
      const response = await storedetailservice
        .getOrgStore()
        .then((response: any) => {
          if (response.success == true) {
            this.oauthToken = response.store.access_token;
            this.current_carousel_name = 'scan';
            this.current_store = response.store;
          }
        })
        .catch((error) => {
          this.current_store = {} as cloudStore;
          throw error;
        });
    },

    async checkAlfred(url: string) {
      try {
        await axios.get(url + '12500/');
        await this.getScanners(url + '12500/');
      } catch (error) {
        try {
          await axios.get(url + '12154/');
          await this.getScanners(url + '12154/');
        } catch (error) {
          try {
            await axios.get(url + '12346/');
            await this.getScanners(url + '12346/');
          } catch (error) {
            this.showDownloadInstallerButton = true;
          }
        }
      }
    },
    async callScanners(url: any) {
      if (url === 'https://local.polydocs.io:') {
        this.checkAlfred(this.valid_url);
      } else {
        this.showDownloadInstallerButton = false;
      }
      this.valid_url = url;
      const response: any = await axios.get(
        addOrgIdQueryString(url + 'scanners'),
      );
      if (response.data.success == true) {
        this.scanners = [];
        response.data.scanners.forEach((scanner: any) => {
          this.scanners.push({
            value: scanner['Host'],
            label: scanner['Device'],
          });
        });
      } else {
        throw 'No scanners found';
      }
    },
    async getScanners(url: any) {
      await this.callScanners(url);
      await this.callScanners(url);
      await this.callScanners(url);
    },
    async doScan() {
      this.showSplitButton = false;
      let url =
        this.valid_url + 'scan?host=' + this.new_scan['source']['value'];
      if (this.new_scan['automatic_get'] == true) {
        url = url + '&source=adf';
      } else {
        url = url + '&source=platen';
      }
      if (this.new_scan['pixel_type']['value'] != '') {
        url = url + '&color=' + this.new_scan['pixel_type']['value'];
      }
      if (this.new_scan['2_sided'] != '') {
        url = url + '&duplex_input=' + this.new_scan['2_sided'];
      }
      const response = await axios
        .get(url, { responseType: 'blob' })
        .then((response) => {
          this.file = URL.createObjectURL(response.data);
          if (this.new_scan['automatic_get']) {
            this.showSplitButton = true;
          }
          this.filedata = response.data;
          this.showDragDrop = false;
          return { message: 'TEST' };
        })
        .catch((error) => {
          logError(error);
          return { message: 'Something failed' };
        });
    },

    async uploadFiles(files: any) {
      for (const file in files) {
        try {
          const formData = new FormData();
          const data = files[file];
          formData.append('file', data);

          await documentdetailservice.ocr_upload_to_store(
            this.new_scan['name'],
            this.current_folder.id,
            this.current_store.id,
            data,
            this.new_scan['auto_doc_name'],
          );
        } catch (err) {
          logError(err);
        }
      }
      if (this.current_folder_url != '') {
        window.open(this.current_folder_url, '_blank');
      }
    },
    async uploadSingleFile() {
      try {
        await documentdetailservice.ocr_upload_to_store(
          this.new_scan['name'],
          this.current_folder.id,
          this.current_store.id,
          this.filedata,
          this.new_scan['auto_doc_name'],
        );
        if (this.current_folder_url != '') {
          window.open(this.current_folder_url, '_blank');
        }
      } catch (err) {
        logError(err);
      }
    },
    async uploadSplitOcr(
      separators: string,
      sorted_indexes: string,
      deleted_indexes: string,
    ) {
      try {
        await documentdetailservice.split_ocr_and_upload_to_store(
          this.new_scan['name'],
          this.current_folder.id,
          this.current_store.id,
          this.filedata,
          this.new_scan['auto_doc_name'],
          separators,
          sorted_indexes,
          deleted_indexes,
        );
        if (this.current_folder_url != '') {
          window.open(this.current_folder_url, '_blank');
        }
      } catch (err) {
        logError(err);
      }
    },

    setShowInstaller() {
      this.showDownloadInstallerButton != this.showDownloadInstallerButton;
    },

    async prepareData() {
      await this.getStore();
      if (this.current_store != null && this.store_type != 'google_drive') {
        await this.loadStoreContent(this.current_store.id);
      }
      this.get_paths_for_org();
    },

    async loadTableDocuments() {
      await documentdetailservice
        .get_directscan_documents()
        .then((response: any) => {
          response.documents.forEach((document: any) => {
            this.documents.push(document);
          });
        })
        .catch((error) => {
          logError(error);
        });
    },

    async loadStoreContent(store_id: string) {
      this.folders = {};
      await alfredSpaceService
        .getFolders(store_id)
        .then((response) => {
          const folder_ids: string[] = [];
          const file_ids: string[] = [];

          response.folders.forEach((folder) => {
            file_ids.push(folder.id);
          });
          response.folders.forEach((folder) => {
            folder_ids.push(folder.id);
          });
          response.folders.forEach((folder) => {
            const folder_obj: cloudFolder = {
              id: folder.id,
              label: folder.label,
              children: [] as any,
              children_ids: [] as any,
              saved: 0,
            };
            this.folders[folder_obj.id] = folder_obj;
            // logInfo('AFTER', this.folders[folder.id])
          });
          this.shown_folders = this.folders;
          this.current_folder = this.root_folder;
        })
        .catch((error) => {
          throw error;
        });
    },

    async init_auth(store_type: string, data: string) {
      const response: any = await storedetailservice
        .init_auth(store_type, data)
        .then((response: any) => {
          window.open(response.url, '_blank');
        })
        .catch((error) => {
          throw error;
        });
    },

    deleteStore(store_id: string) {
      storedetailservice
        .deleteStore(store_id)
        .then((response: any) => {
          this.current_store = {} as cloudStore;
        })
        .catch((error) => {
          throw error;
        });
    },

    setStoreType(store_type: string) {
      this.store_type = store_type;
    },

    setFolder(folder: cloudFolder) {
      this.saved_folders.forEach((saved_folder: any) => {
        if (folder.id == saved_folder.folder_id) {
          folder.saved = 1;
        }
      });
      this.current_folder = folder;
      this.folder_selection = false;
    },

    get_paths_for_org() {
      this.saved_folders = [];
      storedetailservice.get_paths_for_org().then((response: any) => {
        response.paths.forEach((path: any) => {
          const path_obj = {
            label: path.path_name,
            folder_id: path.path_id,
            store_id: path.store,
            id: path.id,
          };
          this.saved_folders.push(path_obj);
        });
      });
    },

    filterFolders(text: string) {
      if (text != '') {
        this.shown_folders = {};
        Object.values(this.folders).forEach((folder: any) => {
          if (folder.label.toUpperCase().includes(text.toUpperCase())) {
            this.shown_folders[folder.id] = folder;
          }
        });
      } else {
        this.shown_folders = this.folders;
      }
    },

    saveFolder(folder_id: string, path_name: string) {
      return storedetailservice.saveFolder(
        this.current_store.id,
        folder_id,
        path_name,
      );
    },
    removeFolder(id: string) {
      return storedetailservice.removeFolder(this.current_store.id, id);
    },
  },
});
