<template>
  <q-card class="split-doc-card">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title
        >{{ $t('split_document') }}<span class="text-weight-bold"></span>
      </q-toolbar-title>

      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>

    <q-card-actions align="right">
      <f-btn apperance="cancel" :label="$t('cancel')" />
      <f-btn
        apperance="tertiary"
        class="q-mr-sm"
        :label="$t('confirm')"
        @click="split_action_confirm = true"
      />
    </q-card-actions>

    <q-card-section class="q-pt-none">
      <div class="main-container">
        <template v-for="page in pageCount" :key="page">
          <span class="box-parent">
            <div draggable="true" class="split-img-main box">
              <q-icon
                flat
                dense
                :data-page-id="page"
                name="cancel"
                size="20px"
                color="red"
                class="img-delete"
                @click="deletePage"
              />
              <vue-pdf-embed
                :data-page-id="page"
                class="split-img"
                :source="doc"
                :page="page"
              />
              <!-- <img
              :data-page-id="index"
              :src="imageMoc"
              class="shadow-5 split-img"
              style="height: auto"

            /> -->
              <!-- @load="
                (evt) => {
                  imageLoaded(evt, index);
                }
              " -->
              <span class="img-number">{{ page }}</span>
            </div>
            <span class="doc-splitter">
              <span
                class="splitter-span"
                @click="addSplit"
                :data-page-id="page"
                :style="{
                  height: splitterHeight + 'px',
                }"
              ></span>
            </span>
          </span>
        </template>
      </div>
    </q-card-section>

    <q-inner-loading :showing="processing">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>

    <q-dialog v-if="split_action_confirm" persistent>
      <q-card>
        <q-card-section
          class="row"
          style="justify-content: center; display: flex"
        >
          <q-avatar icon="warning" color="primary" text-color="white" />
        </q-card-section>

        <q-card-section class="row items-center">
          <span class="q-ml-sm">{{ $t('confirm_split_message') }}</span>
        </q-card-section>

        <q-card-actions align="right">
          <f-btn :label="$t('cancel')" appearance="cancel" />
          <f-btn :label="$t('proceed')" @click="performDocumentSplit()" />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import documentUtil from 'src/utils/documentUtil';
import type { dynamicObj } from 'src/pages/assets';
import { objLen } from 'src/utils/general';
import { ApiExceptions } from 'src/exceptions/index';
import VuePdfEmbed from 'vue-pdf-embed';
import { documentdetailservice } from 'src/doc2light/services/index';
import { useDirectscanStore } from 'src/doc2light/components/scanner_store';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  mixins: [documentUtil],
  props: ['doc', 'pageCount', 'filedata', 'mode'],
  components: {
    VuePdfEmbed,
  },
  data() {
    return {
      dragSrcEl: {} as any,
    };
  },
  watch: {},
  methods: {
    handleDragStart(e: any) {
      e.target.style.opacity = '0.4';
      this.dragSrcEl = e.target;
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/html', e.target.innerHTML);
    },
    handleDragEnd(e: any) {
      e.target.style.opacity = '1';
      let items = document.querySelectorAll('.main-container .box');
      items.forEach(function (item) {
        item.classList.remove('over');
      });
    },
    handleDragOver(e: any) {
      e.preventDefault();
      return false;
    },

    handleDragEnter(e: any) {
      e.target.classList.add('over');
    },

    handleDragLeave(e: any) {
      e.target.classList.remove('over');
    },

    handleDrop(e: any) {
      e.stopPropagation(); // stops the browser from redirecting.
      if (this.dragSrcEl !== e.target) {
        this.dragSrcEl.innerHTML = e.target.innerHTML;
        e.target.innerHTML = e.dataTransfer.getData('text/html');
        const delete_icon = e.target.querySelector('.img-delete');
        if (delete_icon) {
          delete_icon.addEventListener('click', this.deletePage);
        }

        const dragSrcEl_delete_icon =
          this.dragSrcEl.querySelector('.img-delete');
        if (dragSrcEl_delete_icon) {
          dragSrcEl_delete_icon.addEventListener('click', this.deletePage);
        }
      }
      return false;
    },

    deletePage(e: any) {
      let delete_icon_el = e.target;
      if (!delete_icon_el) {
        return;
      }

      let box_el = delete_icon_el.parentNode;
      if (!box_el) {
        return;
      }

      let box_parent_el = box_el.parentNode;
      if (!box_parent_el) {
        return;
      }

      const pageId = Number(delete_icon_el.dataset.pageId);
      this.deleted_indexes.push(pageId);
      box_parent_el.remove();
    },

    afterEvents() {
      let items = document.querySelectorAll('.main-container .box');
      items.forEach((item: any) => {
        item.addEventListener('dragstart', this.handleDragStart);
        item.addEventListener('dragend', this.handleDragEnd);
        item.addEventListener('dragover', this.handleDragOver);
        item.addEventListener('dragenter', this.handleDragEnter);
        item.addEventListener('dragleave', this.handleDragLeave);
        item.addEventListener('drop', this.handleDrop);
      });
    },

    addSplit(event: any) {
      event.stopPropagation();
      let el = event.target as HTMLElement;
      const className = 'split-active';
      if (el.classList.contains(className)) {
        el.classList.remove(className);
        return;
      }
      el.classList.add('split-active');
    },

    getActiveSplits() {
      const selectedSeparators =
        document.querySelectorAll<HTMLElement>('.split-active');
      if (selectedSeparators.length < 1) {
        return [];
      }

      const container = document.querySelector<HTMLElement>('.main-container');
      if (!container) {
        return [];
      }

      let SeparatorsList = [];
      for (var i = 0; i < selectedSeparators.length; i++) {
        let ele = selectedSeparators[i];

        let doc_splitter_el = ele.parentNode;
        if (!doc_splitter_el) {
          continue;
        }
        let box_parent_el = doc_splitter_el.parentNode;
        if (!box_parent_el) {
          continue;
        }

        const page_number = Array.prototype.indexOf.call(
          container.children,
          box_parent_el,
        );
        if (page_number) {
          SeparatorsList.push(Number(page_number) + 1);
        }
      }

      SeparatorsList.push(container.children.length);
      SeparatorsList = this.sortNumbericArray(SeparatorsList);
      return SeparatorsList;
    },

    getActiveSplitters() {
      let selectedSeparators = [] as number[];
      const active_class_name = 'split-active';
      const allSplitter =
        document.querySelectorAll<HTMLElement>('.splitter-span');
      if (allSplitter.length < 1) {
        return [];
      }

      let SeparatorsList = [];
      for (var i = 0; i < allSplitter.length; i++) {
        let ele = allSplitter[i];

        if (!ele.classList.contains(active_class_name)) {
          continue;
        }
        const position = i + 1;
        SeparatorsList.push(position);
      }

      SeparatorsList.push(allSplitter.length);
      SeparatorsList = this.sortNumbericArray(SeparatorsList);
      return SeparatorsList;
    },

    getArrangedPages() {
      this.sorted_indexes = {} as dynamicObj;
      const imagesEl = document.querySelectorAll<HTMLElement>('.split-img');
      if (imagesEl.length < 1) {
        return;
      }

      let sort_document = false;
      for (var i = 0; i < imagesEl.length; i++) {
        let ele = imagesEl[i];

        const pageId = Number(ele.dataset.pageId);
        const ele_index = i + 1;
        if (pageId !== ele_index) {
          sort_document = true;
        }
        this.sorted_indexes[ele_index] = pageId;
      }

      if (!sort_document) {
        this.sorted_indexes = {} as dynamicObj;
      }
    },

    async performDocumentSplit() {
      try {
        this.processing = true;
        let data = {} as dynamicObj;
        let SeparatorsList = this.getActiveSplitters();
        this.getArrangedPages();

        if (objLen(this.sorted_indexes) !== 0) {
          data['sorted_indexes'] = JSON.stringify(this.sorted_indexes);
        }

        if (this.deleted_indexes.length !== 0) {
          data['deleted_indexes'] = this.deleted_indexes.toString();
        }

        if (SeparatorsList.length !== 0) {
          data['separators'] = SeparatorsList.toString();
        }

        if (objLen(data) === 0) {
          this.processing = false;
          this.showFullWidthToast(this.$t('split_empty_warning'));
          return;
        }

        if (this.mode == 'split_create') {
          await documentdetailservice.split_create_doc(
            this.filedata,
            data.separators,
            data.sorted_indexes,
            data.deleted_indexes,
          );
        } else if (this.mode == 'split_only') {
          await documentdetailservice.split_old_doc(
            this.$route.params.id as string,
            data.separators,
            data.sorted_indexes,
            data.deleted_indexes,
          );
        } else if (this.mode == 'ocr_create') {
          await this.scanstore.uploadSplitOcr(
            data.separators,
            data.sorted_indexes,
            data.deleted_indexes,
          );
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
        this.$router.push('/alfred/dashboard');
      }
    },
  },
  setup() {
    let data: any = [];
    const scanstore = useDirectscanStore();

    return {
      processing: ref(false),
      scanstore: scanstore,
      baseUrl: DOC2API_URL,
      split_action_confirm: ref(false),
      splitterHeight: ref(120),
      image_load_count: ref(0),
      deleted_indexes: ref([] as number[]),
      sorted_indexes: ref({} as dynamicObj),

      content: ref([] as any),
      page: ref(),
      showAllPages: ref(true),
      splitter_list: ref([] as any),
    };
  },
});
</script>

