import AbstractApiService from 'src/services/abstractApiService';
import { api, getAuthorizationToken } from 'pages/APIs';
import axios from 'axios';

export default class StoreDetailApiService extends AbstractApiService {
  public constructor({}) {
    super({});
  }

  init_auth(store_type: string, data: string) {
    const formData = new FormData();
    formData.append('store_type', store_type);
    if (store_type == 'dropbox' || store_type == 'lexoffice') {
      formData.append('data', data);
    }
    return super.post(api.init_auth, formData);
  }

  updateStore(id: string, type: string, key: string) {
    let queryParams;
    logInfo(type);
    if (type == 'dropbox') {
      queryParams = '?store_id=' + id + '&store_type=' + type;
      const formData = new FormData();
      formData.append('data', key);
      return super.put(api.edit_store + '/' + queryParams, formData);
    } else {
      queryParams = '?store_id=' + id + '&store_type=' + type;
      return super.put(api.edit_store + '/' + queryParams, new FormData());
    }
  }

  deleteStore(id: string) {
    const queryParams = '?store_id=' + id;
    return super.delete(api.delete_store + queryParams, {});
  }

  ms_auth(queryparams: any) {
    return super.get(api.ms_auth + queryparams);
  }

  getAccessableStores() {
    return super.get(api.get_accessable_user_stores);
  }

  renameStore(store_id: string, name: string) {
    const queryParams = '?store_id=' + store_id + '&name=' + name;
    return super.put(api.rename_store + queryParams, new FormData());
  }

  get_store_content() {
    return super.get(api.get_store_content);
  }

  importFile(path: any): Promise<any> {
    return super.post(api.import_files, path);
  }
  getFolders(): Promise<any> {
    return super.get(api.get_folders);
  }
  toggleStorePublicity(id: string): Promise<any> {
    const queryParams = '?store_id=' + id;
    return super.get(api.toggle_store_publicity + queryParams);
  }
  async downloadFile(path: any): Promise<any> {
    const token = await getAuthorizationToken();
    const response = await axios.post(api.download_files, path, {
      responseType: 'blob',
      headers: {
        Authorization: token,
      },
    });
    return URL.createObjectURL(
      new Blob([
        response.data,
        'Document.pdf',
        response.headers['content-type'],
      ]),
    );
  }

  uploadtostore(path: any) {
    return super.post(api.upload_files, path);
  }

  get_paths_for_org() {
    return super.get(api.get_paths_for_org);
  }

  saveFolder(store_id: string, folder_id: string, path_name: string) {
    const queryParams =
      '?store_id=' +
      store_id +
      '&path_id=' +
      folder_id +
      '&path_name=' +
      path_name;
    return super.post(api.add_update_storepath + queryParams, new FormData());
  }
  removeFolder(store_id: string, folder_id: string) {
    const queryParams = '?store_id=' + store_id + '&id=' + folder_id;
    return super.post(api.add_update_storepath + queryParams, new FormData());
  }

  getOrgStore() {
    return super.get(api.get_org_store);
  }
}
